export function toMerchTransfer(e){if(wx.canIUse("requestMerchantTransfer")){const c={mchId:e.mch_id,appId:e.mch_app_id,package:decodeURIComponent(e.package_info),openId:e.open_id};wx.requestMerchantTransfer(Object.assign(Object.assign({},c),{success(c){"function"==typeof e.success&&e.success(c)},fail(c){"function"==typeof e.fail&&e.fail(c)},complete:function(c){"function"==typeof e.complete&&e.complete(c)}}))}else wx.showModal({content:"你的微信版本过低，请更新至最新版本。",showCancel:!1,success(e){wx.navigateBack()}})}